<!doctype html><html lang="es"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans;font-size:11px}table{width:100%;border-collapse:collapse}td,th{border:1px solid #bbb;padding:6px}h1{color:#173b70}.signature{max-width:260px;max-height:120px}</style></head><body><h1>Registro del servicio de transporte</h1><table><tr><th>Fecha</th><td>{{$s->service_date->format('d/m/Y')}}</td><th>Ruta</th><td>{{$s->route_name_snapshot}}</td></tr><tr><th>Horario programado</th><td>{{$s->scheduled_start_at->format('H:i')}} — {{$s->scheduled_arrival_at->format('H:i')}}</td><th>Horario real</th><td>{{$s->actual_start_at?->format('H:i')??'—'}} — {{$s->actual_arrival_at?->format('H:i')??'—'}}</td></tr><tr><th>Vehículo programado</th><td>{{$s->vehicle?->plate??'—'}}</td><th>Vehículo real</th><td>{{$s->actualVehicle?->plate??'—'}}</td></tr><tr><th>Conductor programado</th><td>{{$s->driver?->display_name??'—'}}</td><th>Conductor real</th><td>{{$s->actualDriver?->display_name??'—'}}</td></tr><tr><th>Pasajeros esperados</th><td>{{$s->expected_passenger_count}}</td><th>Transportados</th><td>{{$s->actual_passenger_count}}</td></tr><tr><th>Recepción</th><td>{{$s->receiver?->nombre_completo??$s->arrival_receiver_name??'—'}}</td><th>Estado</th><td>{{config('transport.service_statuses.'.$s->status,$s->status)}}</td></tr></table><h2>Novedades</h2>@forelse($s->issues as $i)<p><b>{{config('transport.issue_types.'.$i->issue_type)}}</b>: {{$i->description}}</p>@empty<p>Sin novedades.</p>@endforelse @if($signature)<h2>Firma de recepción</h2><img class="signature" src="{{$signature}}"><p>Hash de integridad: {{$s->arrivalSignature->file_hash}}</p>@endif</body></html>
